//! Adapter-owned postconditions. Tool success alone never proves an outcome.
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Compare a JSON pointer in the write arguments with one in a read result.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MatchField {
    pub expected: String,
    pub observed: String,
}

/// Supplied by the application, never generated by the acting model. Identity
/// and changed fields must both match a fresh read of the changed resource.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct VerificationRule {
    pub write_tool: String,
    pub read_tool: String,
    pub identity: Vec<MatchField>,
    pub fields: Vec<MatchField>,
}

impl VerificationRule {
    pub fn validate(&self) -> bool {
        crate::tool::valid_tool_name(&self.write_tool)
            && crate::tool::valid_tool_name(&self.read_tool)
            && !self.identity.is_empty()
            && !self.fields.is_empty()
            && self
                .identity
                .iter()
                .chain(&self.fields)
                .all(|f| f.expected.starts_with('/') && f.observed.starts_with('/'))
    }

    pub fn proves(&self, write_args: &Value, read_tool: &str, output: &Value) -> bool {
        self.validate()
            && self.read_tool == read_tool
            && self.identity.iter().chain(&self.fields).all(|f| {
                let expected = write_args.pointer(&f.expected);
                expected.is_some_and(|v| !v.is_null() && output.pointer(&f.observed) == Some(v))
            })
    }
}

#[derive(Debug)]
pub(crate) struct Pending {
    pub tool: String,
    pub args: Value,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    fn rule() -> VerificationRule {
        VerificationRule {
            write_tool: "update".into(),
            read_tool: "get".into(),
            identity: vec![MatchField {
                expected: "/id".into(),
                observed: "/id".into(),
            }],
            fields: vec![MatchField {
                expected: "/stage".into(),
                observed: "/stage".into(),
            }],
        }
    }
    #[test]
    fn proof_needs_the_right_object_and_the_expected_change() {
        let write = json!({"id":"a", "stage":"ready"});
        assert!(rule().proves(&write, "get", &write));
        assert!(!rule().proves(&write, "search", &write));
        assert!(!rule().proves(&write, "get", &json!({"id":"b","stage":"ready"})));
        assert!(!rule().proves(&write, "get", &json!({"id":"a","stage":"old"})));
        assert!(!rule().proves(&write, "get", &json!({"id":"a"})));
        assert!(!rule().proves(&json!({}), "get", &json!({})));
    }
    #[test]
    fn empty_conditions_cannot_vacuously_prove_an_action() {
        let mut r = rule();
        r.fields.clear();
        assert!(!r.proves(&json!({"id":"a"}), "get", &json!({"id":"a"})));
    }
}
